import { afterAll, beforeAll, describe, expect, test } from "bun:test";
import { chmodSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { recordedInvocations } from "../src/execute";
import { createFixture, wardLauncher, type Fixture } from "../src/fixture";
import { writeRecordingWrapper } from "../src/live";
import { cleanupOwnedProcesses, run, SYSTEM_PATH } from "../src/process";

// Executes the config and wrapper generated by the real `ward integrate junie --guard-approved-specs`
// against the documented Junie CLI hook contract (https://junie.jetbrains.com.cn/docs/junie-cli-hooks.html):
// - Config: `hooks` keyed by event, each entry an optional regular-expression `matcher` and a `hooks`
//   list of `{type: "command", command, timeout}`; Stop takes no matcher; timeout is in seconds
//   (Stop defaults to 600). Commands run through `sh -c` in the session directory.
// - PreToolUse receives `hook_event_name`, `tool_name`, `tool_input`. Exit status 2 refuses the call
//   and shows stderr to the agent; a JSON `decision: deny` on stdout is logged but not enforced
//   (confirmed by a live run: the call still ran).
// - Stop receives `stop_hook_active`; stdout `{"decision":"block","reason":...}` makes Junie retry.
// - There is no post-tool event, so the integration generates no post-edit hook.
// The `tool_input` field names for Write and Edit are assumed to match Claude Code's
// (`file_path`); the documentation does not list them, so a live capture must confirm them.
// The real Ward answers behind a recording wrapper.

const EVENTS = ["SessionStart", "UserPromptSubmit", "PreToolUse", "Stop", "StopFailure", "PermissionRequest", "SessionEnd"];
const MARKER = "# ward-owned: junie-native-hooks v1";
const STOP_TIMEOUT_SECONDS = 600;

let fixture: Fixture;
let unguarded: Fixture;
let config: any;
let log: string;
let bin: string;

beforeAll(async () => {
  const ward = wardLauncher(process.env)!;
  fixture = await createFixture({ harness: "junie", guard: true, ward });
  unguarded = await createFixture({ harness: "junie", guard: false, ward });
  config = JSON.parse(readFileSync(join(fixture.root, ".junie/config.json"), "utf8"));
  bin = join(dirname(fixture.root), "ward-bin");
  log = join(dirname(fixture.root), "ward-log");
  writeRecordingWrapper(bin, log, ward);
  for (const f of [fixture, unguarded]) {
    await run(["/usr/bin/git", "init", "-q"], { cwd: f.root, env: f.env, timeoutMs: 30_000 });
    mkdirSync(join(f.root, "src/main/java"), { recursive: true });
  }
  mkdirSync(join(fixture.root, "openspec/specs/auth"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/specs/auth/spec.md"), "# Auth\n");
  mkdirSync(join(fixture.root, "openspec/changes/add-x"), { recursive: true });
  writeFileSync(join(fixture.root, "openspec/changes/add-x/tasks.md"), "- [ ] 1.1\n");
  writeFileSync(join(fixture.root, "openspec-stub.sh"), '#!/bin/sh\nif [ -f SPEC_FAIL ]; then echo "add-x: missing scenario"; exit 1; fi\n');
  chmodSync(join(fixture.root, "openspec-stub.sh"), 0o755);
  const toml = join(fixture.root, "ward.toml");
  writeFileSync(toml, `${readFileSync(toml, "utf8")}\n[quality-gates.openspec]\nenabled = true\ncommand = ["./openspec-stub.sh"]\n`);
});

afterAll(() => {
  fixture?.cleanup();
  unguarded?.cleanup();
  cleanupOwnedProcesses();
});

const hooks = (event: string, tool?: string, cfg = config) =>
  ((cfg.hooks[event] ?? []) as any[])
    .filter((group) => tool === undefined || !group.matcher || new RegExp(group.matcher).test(tool))
    .flatMap((group) => group.hooks);

/** Runs a hook like Junie: the command through `sh -c` in the session directory, the event on stdin. */
async function launch(f: Fixture, hook: any, payload: unknown, cwd = f.root) {
  const before = recordedInvocations(log).length;
  const env = { ...f.env, CLAUDE_PROJECT_DIR: cwd, PATH: `${bin}:${SYSTEM_PATH}` };
  const stdin =
    typeof payload === "string"
      ? payload
      : JSON.stringify({ session_id: "s", timestamp: "2026-10-16T00:00:00Z", ...(payload as object) });
  const result = await run(["/bin/sh", "-c", hook.command], { cwd, env, stdin, timeoutMs: 60_000 });
  const text = result.stdout.trim();
  let output: any;
  if (text) {
    try {
      output = JSON.parse(text);
    } catch {
      output = { raw: text };
    }
  }
  return { result, output, invocations: recordedInvocations(log).slice(before) };
}

const pre = (name: string, input: Record<string, unknown>, cwd?: string) =>
  launch(fixture, hooks("PreToolUse", name)[0], { hook_event_name: "PreToolUse", tool_name: name, tool_input: input }, cwd);

const stop = (active: boolean) =>
  launch(fixture, hooks("Stop")[0], { hook_event_name: "Stop", stop_hook_active: active, last_assistant_message: "done" });

const blocking = (output: any) => output?.decision === "block" || output?.decision === "deny";

describe("generated config against the Junie CLI hook contract", () => {
  test("every event is one Junie documents, and every hook is a command", () => {
    for (const [event, groups] of Object.entries(config.hooks) as [string, any[]][]) {
      expect(EVENTS).toContain(event);
      for (const group of groups) {
        for (const hook of group.hooks) {
          expect(hook.type).toBe("command");
          expect(typeof hook.command).toBe("string");
        }
      }
    }
  });

  test("the guard runs before Write, Edit, Bash and apply_patch only", () => {
    for (const name of ["Write", "Edit", "Bash", "apply_patch"]) expect(hooks("PreToolUse", name).length).toBe(1);
    expect(hooks("PreToolUse", "Read").length).toBe(0);
  });

  test("Stop runs the check on every turn end, with Junie's 600 second timeout in seconds", () => {
    expect(hooks("Stop").length).toBe(1);
    expect(hooks("Stop")[0].timeout).toBe(STOP_TIMEOUT_SECONDS);
    expect(config.hooks.Stop[0].matcher).toBeUndefined();
  });

  test("Junie has no post-tool event, so no post-edit hook is generated", () => {
    expect(Object.keys(config.hooks).sort()).toEqual(["PreToolUse", "Stop"]);
  });

  test("the ownership marker is at the end of each command", () => {
    for (const event of Object.keys(config.hooks)) {
      for (const h of hooks(event)) expect(h.command.endsWith(MARKER)).toBe(true);
    }
  });
});

describe("hook execution", () => {
  test("the guard refuses a write to an approved spec, from a subdirectory session", async () => {
    const { result, invocations } = await pre(
      "Write",
      { file_path: join(fixture.root, "openspec/specs/auth/spec.md"), content: "# Changed\n" },
      join(fixture.root, "src/main/java"),
    );
    expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "junie", "--guard-approved-specs", "--event-stdin"]]);
    expect(invocations[0].cwd.endsWith("/project")).toBe(true);
    expect(result.exitCode).toBe(2);
    expect(result.stderr).toContain("openspec/specs/auth/spec.md");
  });

  test("the guard refuses an edit to an approved spec", async () => {
    const { result } = await pre("Edit", { file_path: join(fixture.root, "openspec/specs/auth/spec.md"), old_string: "Auth", new_string: "X" });
    expect(result.exitCode).toBe(2);
  });

  test("the guard refuses a patch to an approved spec, which is how Junie edits files", async () => {
    const patch = `*** Begin Patch\n*** Update File: ${join(fixture.root, "openspec/specs/auth/spec.md")}\n@@\n-# Auth\n+# Changed\n*** End Patch`;
    const { result, invocations } = await pre("apply_patch", { patch });
    expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "junie", "--guard-approved-specs", "--event-stdin"]]);
    expect(result.exitCode).toBe(2);
    expect(result.stderr).toContain("openspec/specs/auth/spec.md");
  });

  test("the guard allows an edit in an active change", async () => {
    const { result, output } = await pre("Edit", { file_path: "openspec/changes/add-x/tasks.md", old_string: "[ ]", new_string: "[x]" });
    expect([result.exitCode, blocking(output)]).toEqual([0, false]);
  });

  test("the guard refuses a protected shell command and passes a harmless one", async () => {
    const denied = await pre("Bash", { command: "rm openspec/specs/auth/spec.md" });
    expect(denied.result.exitCode).toBe(2);
    const allowed = await pre("Bash", { command: "ls src" });
    expect([allowed.result.exitCode, blocking(allowed.output)]).toEqual([0, false]);
  });

  test("uninspectable input is refused", async () => {
    const { result } = await launch(fixture, hooks("PreToolUse", "Bash")[0], "{not json");
    expect(result.exitCode).toBe(2);
  });

  test("failing checks at Stop block the stop once with the findings", async () => {
    writeFileSync(join(fixture.root, "SPEC_FAIL"), "");
    try {
      const { output, invocations } = await stop(false);
      expect(invocations.map((i) => i.argv)).toEqual([["hook", "native", "--agent", "junie", "--event-stdin"]]);
      expect(output.decision).toBe("block");
      expect(output.reason).toContain("missing scenario");
    } finally {
      rmSync(join(fixture.root, "SPEC_FAIL"), { force: true });
    }
  });

  test("a Stop already continued by the hook reports the findings without blocking again", async () => {
    writeFileSync(join(fixture.root, "SPEC_FAIL"), "");
    try {
      const { result, output } = await stop(true);
      expect([result.exitCode, blocking(output)]).toEqual([0, false]);
      expect(result.stderr).toContain("missing scenario");
    } finally {
      rmSync(join(fixture.root, "SPEC_FAIL"), { force: true });
    }
  });

  test("with the guard disabled, the pre phase allows without running Ward", async () => {
    const unguardedConfig = JSON.parse(readFileSync(join(unguarded.root, ".junie/config.json"), "utf8"));
    const { result, invocations } = await launch(unguarded, hooks("PreToolUse", "Bash", unguardedConfig)[0], {
      hook_event_name: "PreToolUse",
      tool_name: "Bash",
      tool_input: { command: "rm openspec/specs/auth/spec.md" },
    });
    expect([result.exitCode, result.stdout.trim(), invocations.length]).toEqual([0, "", 0]);
  });
});
